//! Generated parameter matrix seed extracted from `python_arch_reference/i18n/words_matrix.py`.
//!
//! Stage 17 makes the Rust schema/sheaf/parameter runtime depend on the
//! same alias-to-column matrix that `py reta arch` exposes.  The seed keeps
//! only the integer column projection of the legacy bucket tuple; complex
//! bucket semantics stay in their dedicated table/meta/generated modules.

use serde::Serialize;

use crate::schema::ParameterMatrixEntry;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub struct ParameterMatrixSeed {
    pub source_index: usize,
    pub main_aliases: &'static [&'static str],
    pub parameter_aliases: &'static [&'static str],
    pub columns: &'static [i64],
    pub legacy_bucket_count: usize,
}

impl ParameterMatrixSeed {
    pub fn to_entry(self) -> ParameterMatrixEntry {
        ParameterMatrixEntry {
            main_aliases: self.main_aliases.iter().map(|value| (*value).to_string()).collect(),
            parameter_aliases: self.parameter_aliases.iter().map(|value| (*value).to_string()).collect(),
            columns: self.columns.to_vec(),
        }
    }
}

